        let text = CFile::new("Test header.", &["kernel-shared/src/com.rs"]).finish();
        assert!(text.starts_with("/* SPDX-License-Identifier: BSD-3-Clause */\n"));
        assert!(text.contains("GENERATED FILE -- DO NOT EDIT."));
