        for (name, magnitude) in minix_band() {
            assert!(magnitude >= error::MINIX_ERRNO_BASE, "{name}");
        }
        assert_eq!(
            builder::define_value(&render(), "EDEADSRCDST").as_deref(),
            Some("202")
        );
    }

