114	    pub fn define_ep(&mut self, name: &str, value: i32) {
115	        self.define_raw(name, &format!("((endpoint_t) {value})"));
116	    }
117	
118	    /// `#define NAME <text>` with the value column aligned.
119	    pub fn define_raw(&mut self, name: &str, text: &str) {
120	        self.line(&format!("#define {name:<DEFINE_WIDTH$} {text}"));
121	    }
