123	    /// A C11 `_Static_assert`. `msg` must not contain a double quote.
124	    pub fn static_assert(&mut self, expr: &str, msg: &str) {
125	        assert!(
126	            !msg.contains('"'),
127	            "assert message must not contain a quote"
128	        );
129	        self.line(&format!("_Static_assert({expr}, \"{msg}\");"));
130	    }
