 * endpoint proc field instead of using MINIX 3's offset bias (see
 * minix/ipc.h). Naming a task by its _PROC_NR in an IPC call is a bug.
 *
 * The _EP values are computed by calling com::boot_endpoint() in the
 * generator: no equivalent Rust constant exists, and deriving them here is
 * exactly what this tool is for.
 */
#define ASYNCM_PROC_NR           (-5)
#define ASYNCM_EP                ((endpoint_t) 32763)
#define IDLE_PROC_NR             (-4)
#define IDLE_EP                  ((endpoint_t) 32764)
#define CLOCK_PROC_NR            (-3)
#define CLOCK_EP                 ((endpoint_t) 32765)
#define SYSTEM_PROC_NR           (-2)
#define SYSTEM_EP                ((endpoint_t) 32766)
#define HARDWARE_PROC_NR         (-1)
#define HARDWARE_EP              ((endpoint_t) 32767)
#define PM_PROC_NR               0
#define PM_EP                    ((endpoint_t) 0)
#define VFS_PROC_NR              1
#define VFS_EP                   ((endpoint_t) 1)
#define RS_PROC_NR               2
#define RS_EP                    ((endpoint_t) 2)
#define MEM_PROC_NR              3
#define MEM_EP                   ((endpoint_t) 3)
#define TTY_PROC_NR              4
#define TTY_EP                   ((endpoint_t) 4)
#define DS_PROC_NR               5
...
/* ---- endpoint packing self-check ---- */

/*
 * The C decode macros in minix/ipc.h are hand-written; the _EP values are
 * Rust-computed. These assertions check one against the other at compile
 * time, in every translation unit, with no libc and no sysroot.
 */
_Static_assert(SYSTEM_EP == _ENDPOINT(0, SYSTEM_PROC_NR), "SYSTEM_EP disagrees with the _ENDPOINT packing macro");
_Static_assert(_ENDPOINT_P(SYSTEM_EP) == SYSTEM_PROC_NR, "_ENDPOINT_P does not round-trip SYSTEM_EP");
_Static_assert(_ENDPOINT_G(SYSTEM_EP) == 0, "SYSTEM_EP is not a generation-0 boot endpoint");
_Static_assert(HARDWARE_EP == _ENDPOINT(0, HARDWARE_PROC_NR), "HARDWARE_EP disagrees with the _ENDPOINT packing macro");
_Static_assert(_ENDPOINT_P(HARDWARE_EP) == HARDWARE_PROC_NR, "_ENDPOINT_P does not round-trip HARDWARE_EP");
_Static_assert(_ENDPOINT_G(HARDWARE_EP) == 0, "HARDWARE_EP is not a generation-0 boot endpoint");
_Static_assert(CLOCK_EP == _ENDPOINT(0, CLOCK_PROC_NR), "CLOCK_EP disagrees with the _ENDPOINT packing macro");
_Static_assert(_ENDPOINT_P(CLOCK_EP) == CLOCK_PROC_NR, "_ENDPOINT_P does not round-trip CLOCK_EP");
_Static_assert(_ENDPOINT_G(CLOCK_EP) == 0, "CLOCK_EP is not a generation-0 boot endpoint");
_Static_assert(PM_EP == _ENDPOINT(0, PM_PROC_NR), "PM_EP disagrees with the _ENDPOINT packing macro");
_Static_assert(_ENDPOINT_P(PM_EP) == PM_PROC_NR, "_ENDPOINT_P does not round-trip PM_EP");
_Static_assert(_ENDPOINT_G(PM_EP) == 0, "PM_EP is not a generation-0 boot endpoint");
_Static_assert(VFS_EP == _ENDPOINT(0, VFS_PROC_NR), "VFS_EP disagrees with the _ENDPOINT packing macro");
_Static_assert(_ENDPOINT_P(VFS_EP) == VFS_PROC_NR, "_ENDPOINT_P does not round-trip VFS_EP");

